const positions={home:[80,18],set:[50,18],school:[20,18],cafe:[18,47],studio:[18,81],festival:[50,81],gear:[80,81],bank:[81,47]};
const placeCopy={home:['הדירה בפלורנטין','שני שותפים. שלושה תסריטים. אפס חלב.','אמא, בהודעה קולית','״קובי, שמעתי שבהייטק גם יש במאים. קוראים לזה מנהלי מוצר.״'],set:['סט הצילומים','כסף אמיתי. קפה פחות.','ניסים, מנהל הפקה','״יום צילום קצר. שתים־עשרה שעות, גג ארבע־עשרה.״'],school:['בית ספר לקולנוע','כישרון זה חשוב. לדעת איפה הכפתור גם.','דפנה, המרצה','״יש לך קול אישי. עכשיו תוודא ששומעים אותו במיקס.״'],cafe:['קפה קלוז־אפ','פה לא מכירים אנשים. ״נפגשים לקפה״.','שירי, מפיקה עצמאית','״נדבר אחרי החגים. לא אמרתי של איזו שנה.״'],studio:['חדר העריכה','כאן החלום פוגש את החומר המצולם.','מושיק, העורך','״אל תדאג. נסדר את זה בפוסט. אה, אנחנו בפוסט?״'],festival:['הסינמטק','כל הדרך מהדרייב לשטיח האדום.','רוני, מנהלת התוכנייה','״אהבנו מאוד. במיוחד את האורך.״'],gear:['אצל חזי — ציוד','העדשה הזאת ראתה דברים. גם חתונות.','חזי, ״כמו חדש״','״המצלמה עשתה רק סרטי סטודנטים. בקושי עבדה.״'],bank:['בנק שוטף + נצח','המקום שבו ״חשיפה״ היא מילה מדאיגה.','סיגל, יועצת הבנק','״סרט עצמאי? אז מי בדיוק אמור להחזיר את ההלוואה?״']};
for (const loc of G.LOCATIONS) placeCopy[loc.id][0]=loc.name;
const goalDescriptions={wealth:'שיישאר משהו אחרי השכירות',craft:'כי ״יש לי עין״ זה לא מקצוע',reputation:'שיחזירו לך טלפון',happiness:'גם מחוץ לחדר העריכה'};
const goalColors={wealth:'#ceab5c',craft:'#79a7ab',reputation:'#cb7b5c',happiness:'#92a880'};
let state,selected='home',bankTab='funds',festivalFilmId=null,started=false,feedback='',muted=true,toastTimer,dialogReturnFocus=null,lastEnding=null;
let saved=null;
try{const raw=localStorage.getItem(SAVE_KEY);saved=raw?G.validateSave(JSON.parse(raw)):null;muted=localStorage.getItem(SOUND_KEY)!=='on';}catch{}
state=saved||G.createGame({name:'קובי',difficulty:'normal',seed:Date.now()});
function getCharacter(id=state?.characterId||'kobi') { return G.CHARACTERS?.find(c=>c.id===id)||{id:'kobi',name:'קובי',subtitle:'מלך האלתורים',quote:'יהיה בסדר. תמיד יש עוד טייק.',advantage:'צילום חסכוני',drawback:'איכות פחות צפויה',portraitIndex:0}; }
function playablePortrait(id=state?.characterId||'kobi') { const c=getCharacter(id),n=c.portraitIndex;return `<div class="portrait playable-portrait ${id==='amir'?'amir-portrait':''}" role="img" aria-label="${esc(c.name)}" style="--cast-x:${n%2*100}%;--cast-y:${Math.floor(n/2)*100}%"></div>`; }
function portrait(kind='player'){
  if(kind==='player'||kind==='home')return playablePortrait();
  const variants={player:['#3b3335','#2b3f4d','#d79c6e'],rival:['#443029','#9e7172','#daa279'],home:['#815849','#527c71','#e2b18a'],set:['#383234','#c39b59','#bd835c'],school:['#54423c','#807496','#daa87f'],cafe:['#743e2c','#bf715b','#dba47a'],studio:['#392e29','#5a7889','#d89d70'],festival:['#483733','#7d8b57','#dbaa8d'],gear:['#514f45','#8b7858','#c69270'],bank:['#5c3e2d','#65737f','#dbae8c']};
  const [hair,shirt,skin]=variants[kind]||variants.player;
  const idx=({player:0,home:0,set:1,festival:2,cafe:3,school:4,studio:5,gear:6,bank:7,rival:8})[kind]??0;
  return `<div class="portrait portrait-${esc(kind)}" style="--portrait-x:${(Math.max(0,idx)%3)*50}%;--portrait-y:${Math.floor(Math.max(0,idx)/3)*50}%"><svg viewBox="0 0 32 32" shape-rendering="crispEdges" aria-hidden="true"><rect width="32" height="32" fill="#b2b199"/><path d="M6 32V25H10V22H22V25H26V32" fill="${shirt}"/><path d="M12 22V19H20V24H12" fill="${skin}"/><path d="M8 8H24V19H21V22H11V19H8" fill="${skin}"/><path d="M8 6H11V4H22V6H25V13H22V9H12V12H8Z" fill="${hair}"/><path d="M11 14H13V16H11M20 14H22V16H20" fill="#33312d"/><path d="M14 19H19V20H14" fill="#955b49"/>${['rival','studio'].includes(kind)?'<path d="M9 13H15V17H9ZM18 13H24V17H18ZM15 14H18" fill="none" stroke="#36302d"/>':''}</svg></div>`;
}
function save(){if(!started)return;try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));$('save-status').textContent='השמירה עודכנה ✓';}catch{$('save-status').textContent='השמירה אינה זמינה בדפדפן הזה';}}
function beep(ok=true){if(muted)return;try{const ac=beep.ac||(beep.ac=new (window.AudioContext||window.webkitAudioContext)());const o=ac.createOscillator(),g=ac.createGain();o.type='square';o.frequency.value=ok?440:150;g.gain.setValueAtTime(.025,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.13);o.connect(g).connect(ac.destination);o.start();o.stop(ac.currentTime+.14);}catch{}}
function toast(text){$('toast').textContent=textForLife(text);$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),4100);}
